        todo!("construct and check the frozen native model")
    }
}
impl FunderScorer for WeldrsFunderScorer {
    async fn score(&self, input: &ScoringInput)
        -> Result<ScoredPairs, EntityIngestionError>
    {
        todo!("own only profile rows in spawn_blocking, infer, then checked against input")
